    const a = el.querySelector('a[data-testid="result-title-a"]') || el.querySelector('h2 a') || el.querySelector('a');
    return {
      title: a?.textContent?.trim(),
      url: a?.href,
      snippet: el.textContent?.trim().slice(0, 300)
    };
  });
});
console.log("Results count:", results.length);
