args.code:
const tabId = 1675924600;
const generalGuidelines = await browserjs(tabId, () => {
  const buttons = Array.from(document.querySelectorAll('button, a'));
  const btn = buttons.find(b => b.textContent.includes('Guidelines for General Poems') || (b.getAttribute('aria-label') && b.getAttribute('aria-label').includes('General Poems')));
  if (btn) btn.click();
  return { clicked: !!btn };
});
console.log("Clicked:", generalGuidelines);
await new Promise(r => setTimeout(r, 1000));
const details = await browserjs(tabId, () => {
  const modal = document.querySelector('[role="dialog"], .guidelines, [data-testid="guidelines"]') || document.body;
  return modal.innerText;
});
console.log("Guidelines details snippet:\n", details.slice(0, 2000));

